from collections import defaultdict

def topo(edges, nodes):
    outgoing = defaultdict(list)
    indegree = {node: 0 for node in nodes}
    for left, right in edges:
        outgoing[left].append(right)
        indegree[right] += 1
    ready = sorted(node for node in nodes if indegree[node] == 0)
    order = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for nxt in sorted(outgoing[node]):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                ready.append(nxt)
                ready.sort()
    return order if len(order) == len(nodes) else "Zyklus"

print(topo([("build", "test"), ("lint", "test")], ["test", "lint", "build"]))
print(topo([("a", "b"), ("b", "a")], ["a", "b"]))

def topo(edges, nodes):
    incoming = {node: 0 for node in nodes}
    outgoing = {node: [] for node in nodes}
    for left, right in edges:
        outgoing[left].append(right)
        incoming[right] += 1
    ready = sorted(node for node in nodes if incoming[node] == 0)
    result = []
    while ready:
        node = ready.pop(0)
        result.append(node)
        for nxt in outgoing[node]:
            incoming[nxt] -= 1
            if incoming[nxt] == 0:
                ready.append(nxt)
                ready.sort()
    return result if len(result) == len(nodes) else "Zyklus"

print(topo([("a", "c"), ("b", "c")], ["c", "b", "a"]))
print(topo([("b", "c"), ("a", "c")], ["c", "b", "a"]))
